driver_header:
#ifndef PCF8574_H
#define PCF8574_H

#include <stdint.h>
#include "stm32f1xx_hal_i2c.h"

struct pcf8574_dev {
    I2C_HandleTypeDef *bus_handle;
    uint8_t i2c_addr;
};

int pcf8574_init(struct pcf8574_dev *dev, void *bus_handle);
int pcf8574_read_port(struct pcf8574_dev *dev, uint8_t *port_byte);

#endif /* PCF8574_H */

driver_source:
#include "pcf8574.h"
#include <stddef.h>

#include "stm32f1xx_hal_i2c.h"
#define PCF8574_I2C_ADDR 0x20
#define I2C_TIMEOUT 100

int pcf8574_init(struct pcf8574_dev *dev, void *bus_handle)
{
    if (dev == NULL || bus_handle == NULL) {
        return -1;
    }
    dev->bus_handle = (I2C_HandleTypeDef *)bus_handle;
    dev->i2c_addr = PCF8574_I2C_ADDR;
    return 0;
}

int pcf8574_read_port(struct pcf8574_dev *dev, uint8_t *port_byte)
{
    if (dev == NULL || dev->bus_handle == NULL || port_byte == NULL) {
        return -1;
    }
    HAL_StatusTypeDef ret;
    ret = HAL_I2C_Master_Receive(dev->bus_handle, (uint16_t)(dev->i2c_addr << 1), port_byte, 1, I2C_TIMEOUT);
    if (ret != HAL_OK) {
        return -1;
    }
    return 0;
}

